const input = $input.first().json;

const leadInfo = [
  `Nome: ${input.name || 'Desconhecido'}`,
  `Telefone: ${input.phone}`,
  `Stage: ${input.stage || 'new_lead'}`,
  `Score: ${input.score || 0}`,
  `Novo lead: ${input.is_new_lead ? 'Sim' : 'Nao'}`,
  `Canal: ${input.channel || 'whatsapp'}`
].join('\n');

const mensagem = `[INFO DO LEAD]\n${leadInfo}\n\n[MENSAGEM DO LEAD]\n${input.message}`;

return [{
  json: {
    mensagem: mensagem,
    phone: input.phone,
    lead_id: input.lead_id,
    name: input.name,
    stage: input.stage || 'new_lead',
    score: input.score || 0,
    message: input.message,
    is_new_lead: input.is_new_lead,
    channel: input.channel || 'whatsapp'
  }
}];

const agentOutput = $input.first().json;
const context = $('Build Context').first().json;

let fullResponse = agentOutput.output || agentOutput.text || '';
let notifyAdmin = false;
let escalationReason = '';

// Check for human escalation marker
if (fullResponse.includes('[ESCALACAO_HUMANA]')) {
  notifyAdmin = true;
  escalationReason = 'Lead solicitou atendimento humano ou assunto complexo';
  fullResponse = fullResponse.replace('[ESCALACAO_HUMANA]', '').trim();
}

// Extract metadata line
const metaMatch = fullResponse.match(/\[STAGE:(\w+)\|FOLLOWUP:(\d+)\|SCORE_DELTA:([+-]?\d+)\]/);
let stage = context.stage;
let followUpHours = 24;
let scoreDelta = 0;

if (metaMatch) {
  stage = metaMatch[1];
  followUpHours = parseInt(metaMatch[2]);
  scoreDelta = parseInt(metaMatch[3]);
  fullResponse = fullResponse.replace(metaMatch[0], '').trim();
}

const newScore = Math.min(100, Math.max(0, (parseInt(context.score) || 0) + scoreDelta));

return [{
  json: {
    lead_id: context.lead_id,
    phone: context.phone,
    name: context.name,
    response_message: fullResponse,
    suggested_stage: stage,
    follow_up_hours: followUpHours,
    score_delta: scoreDelta,
    new_score: newScore,
    notify_admin: notifyAdmin,
    escalation_reason: escalationReason,
    original_message: context.message
  }
}];
